INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('500e49c6-fe62-46d4-8bd5-2a614ed0fa23', NULL, NULL, NULL, '{"summary": "Posição sólida em pecuária, mas concentração de receita e ameaças tecnológicas exigem diversificação industrial acelerada e expansão de serviços recorrentes.", "threats": [{"source": "análise de mercado", "content": "Tecnologia de pesagem por imagem (câmeras) pode substituir balanças físicas", "confidence": "Média"}, {"source": "fato", "content": "SELIC 14.90% inibe CAPEX de clientes sem acesso a crédito subsidiado", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Entrada de balanças chinesas de baixo custo no segmento de entrada", "confidence": "Média"}, {"source": "análise de mercado", "content": "Concorrentes investindo em troncos hidráulicos e automação total", "confidence": "Média"}], "strengths": [{"source": "fato", "content": "Liderança Top of Mind em troncos e balanças pecuárias com 70+ anos de mercado", "confidence": "Alta"}, {"source": "fato", "content": "Verticalização produtiva com competências em fabricação, eletrônica e sistemas de pesagem", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Rede de assistência técnica já estruturada nacionalmente para Fase 1", "confidence": "Média"}, {"source": "fato", "content": "Portfólio diversificado: madeira/metal, balanças rodoviárias e automação de grãos", "confidence": "Alta"}], "weaknesses": [{"source": "fato", "content": "Dependência crítica do ciclo pecuário (70% da receita) expõe a volatilidade", "confidence": "Alta"}, {"source": "fato", "content": "Receita recorrente de serviços representa apenas 5% - potencial subexplorado", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Ausência de estrutura comercial e técnica para mercado industrial (Fase 2)", "confidence": "Média"}, {"source": "estimativa", "content": "Maturidade digital intermediária (6/10) limita oferta de soluções IoT/SaaS", "confidence": "Média"}], "opportunities": [{"source": "fato", "content": "Plano Safra 2025/26 oferece crédito subsidiado para expansão imediata (Fase 1)", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Pecuária 4.0 e rastreabilidade obrigatória demandam balanças com IoT integrado", "confidence": "Alta"}, {"source": "estimativa", "content": "Expandir serviços de calibração/manutenção para gerar receita recorrente (+15%)", "confidence": "Média"}, {"source": "análise de mercado", "content": "Diversificação industrial reduz exposição ao ciclo pecuário e abre novo TAM", "confidence": "Média"}]}'::jsonb, '{"legal": ["Rastreabilidade bovina individual obrigatória (potencial) cria demanda mandatória por balanças com identificação eletrônica", "NR-12 e certificação INMETRO são barreiras de entrada que protegem Coimma de concorrentes informais e importados", "Portarias INMETRO para instrumentos de pesagem exigem compliance contínuo - vantagem competitiva para marca consolidada"], "social": ["Bem-estar animal (BEA) como exigência de mercados exportadores reforça valor de troncos de contenção humanizados Coimma", "Escassez de mão de obra qualificada no campo acelera demanda por automação de pesagem e manejo - oportunidade Fase 1", "Sucessão geracional no agro traz gestores mais digitais, receptivos a balanças IoT integradas a software de gestão"], "summary": "Ambiente favorável à Fase 1 via Plano Safra, mas SELIC alta limita CAPEX privado. Tendências de Pecuária 4.0 e ESG abrem oportunidades, porém ameaças tecnológicas (pesagem por imagem) e concorrência em automação exigem inovação acelerada.", "economic": ["SELIC 14.90% eleva custo de CAPEX dos clientes - vendas dependem fortemente de linhas subsidiadas do Plano Safra", "Câmbio USD/BRL 5.34 encarece componentes eletrônicos importados, pressionando margens em balanças digitais e automação", "PIB +3.20% e desemprego 5.60% sustentam demanda, mas produtor rural cauteloso prioriza investimentos essenciais"], "political": ["Plano Safra 2025/26 com crédito subsidiado é alavanca crítica para vendas de equipamentos pecuários - janela de oportunidade imediata", "Reforma Tributária em curso pode alterar carga fiscal sobre bens de capital industriais - monitorar impacto em precificação Fase 2", "Estabilidade política favorece planejamento de médio prazo, mas dependência de políticas agrícolas expõe a ciclos eleitorais"], "environmental": ["Normas ESG mais rígidas na cadeia da carne exigirão rastreabilidade e certificações - oportunidade para balanças conectadas", "Pressão por redução de pegada de carbono na pecuária pode valorizar equipamentos que otimizam manejo e reduzem perdas", "Custos elevados de nutrição animal podem retrair investimentos em pecuária intensiva - risco para segmento confinamentos"], "technological": ["Pecuária 4.0 com IoT e gestão de dados é tendência dominante - Coimma precisa acelerar integração digital em balanças", "AMEAÇA: SaaS de pesagem por imagem (câmeras) pode substituir balanças físicas no longo prazo - monitorar startups", "Concorrentes investindo em troncos hidráulicos e automação total - risco de perda de liderança sem inovação contínua"]}'::jsonb, '{"summary": "Setor com atratividade média: barreiras protegem incumbentes, mas poder de compra elevado (SELIC 14.90%) e ameaças tecnológicas (pesagem por imagem, IoT) exigem transformação. Coimma deve alavancar liderança em troncos para construir ecossistema digital, expandir serviços recorrentes e diversificar para industrial, reduzindo exposição ao ciclo pecuário.", "buyer_power": "Poder alto: Produtor rural cauteloso com SELIC 14.90%. Dependência de crédito subsidiado (Plano Safra 2025/26) concentra decisões de compra. Clientes exigem ROI claro e condições de financiamento competitivas.", "supplier_power": "Poder médio: Aço estável com viés de alta pressiona custos. Câmbio USD/BRL 5.34 encarece eletrônicos importados. Cadeia normalizada, mas dependência de componentes eletrônicos importados representa vulnerabilidade estratégica.", "disruption_ai_data": "Disrupção média-alta: Pecuária 4.0 demanda IoT e analytics. Balanças conectadas geram dados valiosos. Quem dominar plataforma de dados de pesagem captura valor recorrente. Risco de commoditização do hardware.", "threat_substitutes": "Ameaça média-alta: SaaS de pesagem por imagem (câmeras) emerge como substituto de longo prazo. Tecnologia pode eliminar balanças físicas em aplicações específicas. Exige monitoramento e potencial pivot para soluções híbridas.", "competitive_rivalry": "Rivalidade moderada-alta: Toledo, Beckhauser e Açores disputam segmentos premium. Consolidação em AgTechs acelera. Coimma lidera em troncos (Top of Mind), mas concorrentes investem em hidráulicos e automação total, exigindo inovação contínua.", "threat_new_entrants": "Ameaça baixa-média: Barreiras altas (escala, rede técnica, INMETRO, NR-12). Porém, balanças chinesas de baixo custo penetram segmento de entrada. Reputação de 70 anos da Coimma é diferencial defensivo.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Média", "strategic_implications": ["Desenvolver plataforma IoT/dados para balanças, criando receita recorrente SaaS e reduzindo dependência de venda de hardware", "Estabelecer parcerias com ERPs agrícolas (ex: Aegro, Prodap) e fintechs de crédito rural para facilitar financiamento e integração", "Expandir serviços de calibração/manutenção de 5% para 15% do faturamento, criando base recorrente e relacionamento contínuo", "Acelerar entrada no segmento industrial (Fase 2) para diversificar além dos 70% de dependência pecuária, mitigando ciclicidade"], "supplier_power_intensity": "Média", "disruption_ai_data_intensity": "Média", "threat_substitutes_intensity": "Média", "competitive_rivalry_intensity": "Média", "power_partnerships_ecosystems": "Poder estratégico alto: Consolidação AgTech cria oportunidades de integração com softwares de gestão pecuária. Parcerias com ERPs agrícolas e fintechs de crédito rural podem ampliar proposta de valor e lock-in.", "threat_new_entrants_intensity": "Baixa", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": "90 dias para lançar Coimma Care, estruturar vertical de grãos/logística e iniciar validação do mercado industrial, reduzindo dependência pecuária.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Estruturar o programa Coimma Care e mapear oportunidades de expansão comercial nas regiões Centro-Oeste e Norte", "investment": "R$ 150-200 mil", "key_results": ["Desenhar 3 pacotes de serviço Coimma Care (básico, intermediário, premium) com precificação validada", "Mapear 150 clientes ativos sem contrato de manutenção nas regiões prioritárias para prospecção", "Implementar CRM com pipeline de vendas e módulo de gestão de contratos de serviço configurado"], "aligned_recommendation": "Expansão Comercial Fase 1 com Motor de Serviços Recorrentes"}, {"focus": "Crescimento", "month": "Mês 2", "objective": "Lançar Coimma Care no mercado e iniciar estruturação da vertical de Grãos e Logística", "investment": "R$ 200-300 mil", "key_results": ["Converter 30 clientes existentes para contratos Coimma Care (meta: R$ 80k em receita recorrente mensal)", "Contratar e treinar 2 vendedores especializados para vertical de grãos e logística rodoviária", "Fechar 5 reuniões comerciais com cooperativas agrícolas e operadores logísticos de grande porte"], "aligned_recommendation": "Diversificação para Grãos e Logística Rodoviária"}, {"focus": "Consolidação", "month": "Mês 3", "objective": "Escalar vendas com serviços atrelados e validar primeiras oportunidades no segmento industrial", "investment": "R$ 250-350 mil", "key_results": ["Atingir 50 contratos Coimma Care ativos e elevar serviços para 7% do faturamento mensal", "Gerar R$ 500k em pipeline qualificado para balanças de fluxo e automação rodoviária", "Realizar estudo de mercado industrial com 15 entrevistas em mineração, siderurgia e química"], "aligned_recommendation": "P&D e Piloto para Segmento Industrial (Preparação Fase 2)"}], "success_metrics": ["Receita de serviços recorrentes elevada de 5% para 7%+ do faturamento", "Pipeline comercial de R$ 1.5M+ gerado nos segmentos de grãos e logística", "Base de 50+ clientes com contratos Coimma Care ativos"], "total_investment": "R$ 600-850 mil"}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Lançar Coimma Care, estruturar vertical grãos/logística, intensificar presença em feiras e visitas técnicas", "Médio Prazo (6-12 meses): Implementar IoT nas balanças, desenvolver plataforma digital de orçamento, iniciar P&D para produtos industriais", "Longo Prazo (12+ meses): Go-to-market industrial com modelo ''Balança como Serviço'', estruturar nova equipe comercial e assistência técnica"], "key_findings": ["Transformação de vendedor de hardware para provedor de soluções integradas é imperativa para sustentabilidade competitiva", "Serviços recorrentes (Coimma Care) podem triplicar de 5% para 15-20%, criando previsibilidade de receita e lock-in", "Ecossistema digital com dados fazenda-armazém-indústria-logística cria barreira competitiva impossível de replicar"], "main_findings": ["FORÇA: Marca consolidada com liderança Top of Mind em troncos e balanças, verticalização produtiva e 70+ anos de reputação", "FRAQUEZA: Dependência crítica da pecuária (70%) e baixa receita recorrente de serviços (apenas 5% do faturamento)", "OPORTUNIDADE: Pecuária 4.0, IoT e ESG abrem mercado para soluções digitais integradas e modelo de serviços recorrentes", "AMEAÇA: Pesagem por imagem (câmeras) pode substituir balanças físicas no longo prazo; SELIC 14.90% freia investimentos"], "important_notes": ["SELIC a 14.90% limita CAPEX de clientes - priorizar modelos de financiamento e Plano Safra", "Pesagem por imagem é ameaça de longo prazo - investir em IoT e dados como diferencial competitivo", "Validar mercado industrial rigorosamente antes de investimentos pesados na Fase 2"], "central_challenge": "Reduzir dependência do ciclo pecuário (70% da receita) através de diversificação para mercado industrial e expansão de serviços recorrentes, transformando a Coimma de vendedora de hardware para provedora de soluções integradas.", "executive_summary": "A Coimma, líder com 70+ anos em equipamentos de pesagem, enfrenta concentração crítica na pecuária. A estratégia em duas fases visa: (1) expandir vendas atuais e elevar serviços de 5% para 15-20% via Coimma Care e IoT; (2) penetrar mercado industrial com modelo ''Balança como Serviço''. SELIC alta limita CAPEX de clientes, mas Plano Safra e tendências de Pecuária 4.0 criam janela de oportunidade.", "strategic_priorities": ["Lançar Coimma Care em 90 dias para expandir receita recorrente de serviços", "Diversificar para grãos/logística reduzindo exposição ao ciclo pecuário", "Validar mercado industrial antes de investimentos estruturais da Fase 2"], "overall_recommendation": "Executar Fase 1 com foco em serviços recorrentes e diversificação para grãos, validando sinais de mercado industrial antes de comprometer capital na Fase 2. A janela de oportunidade em Pecuária 4.0 é agora."}'::jsonb, '{"sam": "R$ 4.5B - R$ 6.5B", "som": "R$ 450M - R$ 750M", "tam": "R$ 18B - R$ 25B", "cagr": "+6% a +9% a.a. (baseado em: crescimento setor máquinas agrícolas CNI/ABIMAQ + Pecuária 4.0)", "summary": "Coimma opera em mercado de R$18-25B com posição dominante em nichos. Potencial de captura R$450-750M com expansão atual + novos segmentos industriais podem adicionar R$200-400M ao SOM em 5 anos.", "assumptions": ["TAM: Mercado brasileiro de máquinas agrícolas (ABIMAQ 2024) + balanças industriais (INMETRO)", "SAM: 25% TAM = segmentos pecuária intensiva + grãos + logística rodoviária atendíveis", "SOM: 10-12% SAM = posição de líder consolidado (Top of Mind) com 70+ anos de mercado"], "confidence_level": 68, "calculation_notes": "TAM derivado de ABIMAQ (máq. agrícolas R$15-20B) + balanças industriais (R$3-5B). SAM filtrado por segmentos core. SOM baseado em liderança declarada e receita estimada R$150-300M.", "data_sources_used": {"direct_data": ["Receita Coimma estimada R$150-300M (intelligence)", "Market share: Líder Top of Mind em troncos/balanças pecuárias", "Setor máquinas agrícolas crescimento +5-8% (macro_context)"], "proxy_calculations": ["Toledo do Brasil (concorrente): receita ~R$1.5B → Coimma ~15-20% do líder em balanças", "Mercado balanças rodoviárias Brasil: ~R$800M-1.2B (Saturno + Toledo + regionais)", "Mercado troncos contenção: ~R$300-500M (Beckhauser + Romancini + Açores + Coimma)"], "benchmark_extrapolations": ["Agronegócio/AgTech Brasil TAM ~R$1.2T → subsegmento máquinas/equipamentos ~2%", "Receita/funcionário setor metalmecânico: R$400-600K → 300 func × R$500K = R$150M (validado)"]}, "estimation_method": "proxy_concorrentes"}'::jsonb, '{"summary": "A Coimma lidera em troncos e balanças pecuárias com marca forte de 70+ anos, mas apresenta gaps críticos em monetização de serviços recorrentes (5% vs. 15-25% do mercado) e digitalização. Toledo do Brasil é benchmark em capilaridade industrial e contratos de manutenção. Saturno destaca-se em automação rodoviária com software antifraude. Para a Fase 1, priorizar expansão de contratos de serviços no portfólio atual pode elevar receita recorrente em 3x. Na Fase 2, o desenvolvimento de plataforma IoT e estrutura comercial industrial são pré-requisitos para competir fora do nicho pecuário. O mercado endereçável de R$18-25B oferece espaço significativo, mas exige investimento em digitalização e força de vendas especializada.", "best_practices": ["Toledo: Modelo de contrato de manutenção preventiva com recorrência mensal gerando previsibilidade de receita.", "Saturno: Automação completa de balanças rodoviárias com integração ERP e antifraude, agregando valor ao hardware.", "Beckhauser: Foco em bem-estar animal certificado como diferencial premium para exportadores de carne."], "performance_gaps": ["Receita recorrente (serviços) de apenas 5% vs. 15-25% dos concorrentes como Toledo que monetizam manutenção e calibração.", "Ausência de plataforma IoT/SaaS integrada enquanto Toledo e Saturno oferecem dashboards de gestão de pesagem em nuvem.", "Estrutura comercial industrial inexistente vs. Toledo com equipe dedicada e capilaridade nacional para indústria."], "competitors_analyzed": ["Toledo do Brasil", "Beckhauser", "Saturno Inteligência Industrial", "Açores", "Romancini"]}'::jsonb, '{"raise": ["Contratos de serviço recorrente com SLA e calibração programada", "Integração IoT nativa em todas as balanças (dados em nuvem)", "Capacitação técnica certificada para rede de assistência"], "create": ["Plataforma SaaS de gestão de pesagem com analytics preditivo", "Modelo de assinatura ''Balança como Serviço'' (BaaS) para PMEs", "Ecossistema digital conectando pecuária, grãos e logística industrial"], "reduce": ["Ciclo de vendas longo com múltiplas visitas presenciais", "Customizações de baixo valor que atrasam produção", "Estoque de peças sobressalentes descentralizado e ineficiente"], "summary": "A estratégia transforma a Coimma de vendedora de hardware para provedora de soluções integradas de pesagem. Na Fase 1, elimina-se o modelo transacional puro, criando vínculos digitais via IoT e contratos de serviço recorrente que elevam os 5% atuais para 20%+ do faturamento. Reduz-se a dependência de vendas presenciais com plataforma digital de configuração e orçamento. Na Fase 2, o ''Balança como Serviço'' democratiza acesso ao segmento industrial sem CAPEX pesado do cliente, enquanto a plataforma SaaS captura dados de toda a cadeia (fazenda-armazém-indústria-logística), criando lock-in e diferenciação impossível de replicar por concorrentes focados apenas em hardware. O ecossistema digital posiciona a Coimma como hub de inteligência de pesagem, reduzindo exposição ao ciclo pecuário e criando barreiras competitivas baseadas em dados, não apenas em metal.", "eliminate": ["Venda transacional única sem vínculo digital com cliente", "Catálogos impressos e orçamentos manuais demorados", "Dependência exclusiva de revendedores sem dados de uso"], "new_value_curve": "De fabricante de equipamentos para orquestrador de dados de pesagem com receita recorrente e ecossistema digital integrado."}'::jsonb, '{"summary": "Fase 1: Escalar aquisição via feiras e visitas técnicas, monetizando com serviços recorrentes. Fase 2: Expandir LTV com cross-sell industrial e IoT.", "leap_loop": {"name": "LEAP Loop", "type": "acquisition", "steps": ["Land: Feiras agropecuárias (Expozebu, Feicorte), Google Ads para ''balança bovina'', parcerias com revendas rurais e cooperativas agrícolas.", "Engage: Demonstrações presenciais em fazendas, webinars sobre Pecuária 4.0, conteúdo técnico (ROI de pesagem precisa, bem-estar animal).", "Activate: Visita técnica gratuita para dimensionamento, financiamento via Plano Safra, proposta em 24h com simulação de payback.", "Propagate: Programa ''Indicou, Ganhou'' para pecuaristas, cases de sucesso em vídeo, selo ''Fazenda Parceira Coimma'' para clientes."], "metrics": ["CAC por canal (Feiras vs Digital vs Revendas)", "Taxa de conversão Visita Técnica → Proposta → Venda", "Coeficiente de indicação (novos leads por cliente ativo)", "Custo por Lead Qualificado (SQL)"], "bottleneck": "Capacidade limitada de visitas técnicas presenciais para ativação em regiões distantes de Dracena-SP, alongando ciclo de vendas."}, "scale_loop": {"name": "SCALE Loop", "type": "monetization", "steps": ["Satisfy: Entrega com instalação inclusa, treinamento operacional, suporte técnico 24h via WhatsApp e garantia estendida.", "Convert: Upsell de automação e IoT em balanças básicas, contratos anuais de calibração INMETRO, pacotes de manutenção preventiva.", "Loop Back: Alertas automáticos de recalibração, programa de fidelidade com descontos progressivos, visitas semestrais de relacionamento.", "Expand: Cross-sell de novos equipamentos (tronco → balança → automação), upgrade para Pecuária 4.0, expansão para grãos/industrial."], "metrics": ["LTV (Lifetime Value) por segmento (Pecuária vs Grãos vs Industrial)", "Taxa de adesão a contratos de serviços recorrentes", "Receita de expansão (% de clientes que compram 2º produto)", "NPS e taxa de recompra em 24 meses"], "bottleneck": "Baixa penetração de serviços recorrentes (apenas 5% do faturamento), desperdiçando potencial de receita previsível e relacionamento."}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "SELIC permanece entre 13-15% até 2026, limitando CAPEX privado. Plano Safra sustenta demanda básica, mas produtor prioriza reposição sobre expansão. Crescimento do setor em +5-6%. Concorrência chinesa pressiona margens no segmento entrada. Câmbio USD/BRL 5.30-5.50 encarece eletrônicos em 8%. Fase 1 viável com crescimento de 10-15%, mas Fase 2 industrial exige cautela e validação de mercado antes de investimentos pesados.", "probability": 60, "required_actions": ["Intensificar vendas consultivas focando ROI e redução de perdas para justificar investimento", "Desenvolver linha de entrada competitiva para barrar concorrência chinesa", "Criar programa de trade-in para renovação de base instalada", "Pilotar Fase 2 com 2-3 clientes industriais antes de estruturação comercial completa"]}, "summary": "A Coimma opera em ambiente de incerteza moderada. O cenário realista (60%) permite execução cautelosa da Fase 1 com crescimento de 10-15%, mas exige validação rigorosa antes da Fase 2. Principais riscos: dependência excessiva da pecuária (70%), SELIC elevada limitando CAPEX de clientes, e ameaça tecnológica de longo prazo (pesagem por imagem). Mitigação prioritária: diversificar para grãos/logística, expandir serviços recorrentes de 5% para 15%, e manter vigilância sobre sinais de SELIC, Plano Safra e preço da arroba. A solidez de 70+ anos e liderança de mercado são ativos defensivos, mas inovação em IoT e Pecuária 4.0 é imperativa para sustentabilidade competitiva.", "optimistic": {"name": "Cenário Otimista", "description": "SELIC cai para 11% até 2026, Plano Safra 2025/26 libera R$400bi+ com taxas subsidiadas de 7%. Arroba do boi estabiliza em R$320, impulsionando CAPEX pecuário. Rastreabilidade individual torna-se obrigatória, gerando demanda massiva por balanças IoT. Reforma tributária simplifica IBS, reduzindo carga em 15%. Coimma captura 35% do mercado de Pecuária 4.0, expandindo serviços recorrentes para 12% do faturamento.", "probability": 20, "required_actions": ["Acelerar lançamento de balanças com IoT integrado e dashboard de gestão de rebanho", "Firmar parcerias com bancos para financiamento direto via Plano Safra aos clientes", "Expandir equipe comercial em 30% para capturar demanda de rastreabilidade obrigatória"]}, "pessimistic": {"name": "Cenário Pessimista", "description": "SELIC sobe para 16%+, arroba despenca para R$240 por retração de exportações. Custos de nutrição inviabilizam confinamentos. Plano Safra sofre cortes de 20%. Tecnologia de pesagem por imagem (SaaS) ganha tração, ameaçando balanças físicas em 5 anos. Aço sobe 15%, comprimindo margens. Reforma tributária aumenta carga no setor industrial. Faturamento pecuário cai 25%, forçando reestruturação e adiamento indefinido da Fase 2.", "probability": 20, "required_actions": ["Cortar custos fixos em 15% e postergar investimentos em Fase 2", "Pivotar para serviços de manutenção e calibração como receita defensiva", "Desenvolver parceria ou aquisição de startup de pesagem por imagem para hedge tecnológico"]}, "mitigation_tactics": ["Diversificar receita: acelerar penetração em grãos e logística rodoviária para reduzir dependência pecuária de 70% para 55% em 3 anos", "Expandir serviços recorrentes: criar contratos de manutenção preventiva e calibração periódica, elevando de 5% para 15% do faturamento", "Hedge cambial: negociar contratos de fornecimento de componentes eletrônicos com trava de câmbio de 6-12 meses", "Inovação defensiva: investir em P&D de integração IoT e monitorar ativamente tecnologias disruptivas como pesagem por imagem"], "early_warning_signals": ["Decisões do COPOM sobre SELIC: quedas consecutivas de 0.5pp sinalizam cenário otimista; manutenção ou alta indica pessimista", "Volume de liberações do Plano Safra nos primeiros 90 dias: abaixo de 60% do projetado indica retração", "Preço da arroba do boi: queda sustentada abaixo de R$280 por 60 dias sinaliza crise no setor", "Movimentação de concorrentes em automação e entrada de novos players chineses em licitações públicas", "Anúncios regulatórios do MAPA sobre rastreabilidade individual obrigatória"]}'::jsonb, '{"summary": "O BSC alinha a transformação da Coimma de fabricante de hardware para hub de inteligência de pesagem. Os objetivos financeiros garantem diversificação e receita recorrente. A perspectiva de clientes foca em criar vínculos digitais e penetrar o mercado industrial. Processos internos priorizam digitalização comercial e inovação de produto. Aprendizado sustenta a mudança com capacitação e estrutura de P&D, criando barreiras competitivas baseadas em dados e ecossistema integrado.", "customer": ["Atingir 40% de clientes conectados via IoT com contratos de serviço recorrente", "Conquistar 50 novos clientes industriais com modelo ''Balança como Serviço''"], "financial": ["Elevar receita recorrente (serviços/SaaS) de 5% para 20% do faturamento até 2027", "Reduzir dependência pecuária de 70% para 50% via diversificação industrial"], "learning_growth": ["Capacitar 100% da equipe comercial em venda consultiva de soluções integradas", "Estruturar squad de P&D em IoT/software com 15 especialistas dedicados"], "internal_processes": ["Lançar plataforma digital de configuração/orçamento com 80% das vendas habilitadas", "Desenvolver 3 novos produtos industriais integrados à plataforma SaaS de dados"]}'::jsonb, '{"score": "7.8/10", "summary": "A Estratégia C maximiza o aproveitamento da estrutura existente e da liderança de mercado da Coimma (70+ anos), enquanto mitiga o risco de concentração na pecuária. A Fase 1 gera caixa e fortalece a base de clientes com serviços recorrentes (margem superior), criando resiliência financeira para os investimentos da Fase 2. A diversificação para grãos/logística é natural (competências existentes) e menos arriscada que o salto direto para industrial. O P&D paralelo em IoT e novos produtos industriais posiciona a Coimma para capturar oportunidades de Pecuária 4.0 e novos mercados sem comprometer a operação core. Próximos passos: (1) Aprovar orçamento de R$ 800k-1.2M para Fase 1 imediata; (2) Contratar líder de serviços recorrentes em 60 dias; (3) Agendar workshop de P&D industrial em 90 dias.", "criteria": ["ROI e Payback (Retorno sobre investimento em 24 meses)", "Mitigação de Risco de Concentração (Redução da dependência pecuária de 70%)", "Viabilidade de Execução (Compatibilidade com estrutura atual e capacidade de investimento)"], "alternatives": ["Estratégia A: Expansão Agressiva em Pecuária + Diversificação Gradual (Foco Fase 1 intensificada)", "Estratégia B: Diversificação Acelerada para Industrial + Serviços Recorrentes (Foco Fase 2 antecipada)", "Estratégia C: Expansão Equilibrada Faseada com Fortalecimento de Serviços (Híbrida Fase 1→2)"], "review_cycle": {"frequency": "Trimestral (Comitê Estratégico com CEO e Diretoria)", "extraordinary_triggers": ["Variação superior a 15% na arroba do boi em 60 dias", "Alteração na SELIC acima de 1.5 p.p. em ciclo único do COPOM", "Mudança significativa no Plano Safra ou crédito rural subsidiado", "Entrada de competidor relevante com tecnologia disruptiva (ex: pesagem por imagem)", "Oportunidade de aquisição ou parceria estratégica no setor industrial", "Desvio superior a 20% em qualquer KPI crítico de execução"]}, "score_comparison": "+18% acima da segunda opção (Estratégia A: 6.6/10) e +30% acima da terceira (Estratégia B: 6.0/10)", "monitoring_metrics": ["Receita por segmento (% Pecuária vs. Grãos/Industrial vs. Serviços) - Meta: Pecuária ≤60%, Serviços ≥12%", "Taxa de conversão de vendas por canal e região (Meta: +15% vs. baseline)", "Receita recorrente de serviços (calibração/manutenção) - Meta: 12-15% do faturamento em 12 meses", "NPS (Net Promoter Score) de clientes por segmento - Meta: ≥70", "Pipeline de novos produtos industriais (estágio de desenvolvimento e pilotos ativos)", "Custo de Aquisição de Cliente (CAC) por segmento e payback de novos clientes", "Market share em troncos e balanças pecuárias (manter liderança Top of Mind)"], "recommended_option": "Estratégia C: Expansão Equilibrada Faseada com Fortalecimento de Serviços (Híbrida Fase 1→2)", "final_recommendation": "Adotar Estratégia C: crescimento faseado equilibrado, priorizando expansão comercial imediata com portfólio atual + triplicar receita de serviços recorrentes (de 5% para 15%), enquanto prepara entrada industrial com P&D estruturado.", "priority_recommendations": [{"title": "Expansão Comercial Fase 1 com Motor de Serviços Recorrentes", "budget": "R$ 800k - R$ 1.2M (Força de vendas + CRM + Estruturação de serviços)", "priority": 1, "timeline": "0-12 meses", "description": "Intensificar vendas do portfólio atual (troncos, balanças bovinas e rodoviárias) nas regiões Centro-Oeste e Norte, aproveitando a estrutura existente. Simultaneamente, estruturar oferta de contratos de manutenção preventiva e calibração como ''Coimma Care'', elevando serviços de 5% para 12-15% do faturamento. Criar pacotes de serviço atrelados à venda de equipamentos novos com desconto de adesão."}, {"title": "Diversificação para Grãos e Logística Rodoviária", "budget": "R$ 1.5M - R$ 2.5M (Equipe comercial + Marketing setorial + Adequações técnicas)", "priority": 2, "timeline": "6-18 meses", "description": "Acelerar penetração no segmento de grãos e armazenamento (atualmente 30%) com foco em balanças de fluxo por batelada e automação de balanças rodoviárias. Desenvolver parcerias com cooperativas agrícolas e operadores logísticos. Criar vertical comercial dedicada com 3-5 vendedores especializados e material técnico específico para o setor."}, {"title": "P&D e Piloto para Segmento Industrial (Preparação Fase 2)", "budget": "R$ 2M - R$ 3.5M (P&D + Protótipos + Estrutura comercial piloto + Assistência técnica)", "priority": 3, "timeline": "12-24 meses", "description": "Iniciar desenvolvimento de produtos para segmento industrial (mineração, siderurgia, química) com base nas competências de pesagem e eletrônica. Realizar estudo de mercado, desenvolver 1-2 protótipos e executar 3-5 projetos-piloto com clientes estratégicos. Estruturar roadmap de IoT e Pecuária 4.0 para manter competitividade no core business."}]}'::jsonb, 'completed', NULL, 141509, false, false, false, 'Z18IAKCH', '2025-11-27 21:02:26.332953+00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-27 20:56:31.976512+00'::timestamptz, '2025-11-28 05:44:03.770068+00'::timestamptz, '2025-11-27 20:58:53.20294+00'::timestamptz, NULL)
