-- Row 30: 2e3e58b6-d003-460c-bf66-5f4590445445
INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('2e3e58b6-d003-460c-bf66-5f4590445445', NULL, NULL, NULL, '{"summary": "Boutique bem posicionada em mercado aquecido, mas crescimento exige profissionalização urgente: estruturar vendas, reduzir dependência do fundador e criar plano de carreira para reter talentos.", "threats": [{"source": "análise de mercado", "content": "Consultorias de TI (Big4) entrando em compliance LGPD com escala e preços agressivos", "confidence": "Alta"}, {"source": "análise de mercado", "content": "IA generativa automatizando serviços jurídicos básicos pressiona margens de contencioso", "confidence": "Média"}, {"source": "análise de mercado", "content": "Escassez de advogados sêniores em tech law inflaciona custos e limita expansão", "confidence": "Alta"}, {"source": "fato", "content": "SELIC a 15% encarece capital para expansão e reduz apetite de clientes por projetos", "confidence": "Média"}], "strengths": [{"source": "fato", "content": "Hiperespecialização em Direito Digital e LGPD com 7 anos de mercado e reputação consolidada", "confidence": "Alta"}, {"source": "fato", "content": "Meta clara de lucratividade >40% demonstra disciplina financeira e foco em rentabilidade", "confidence": "Alta"}, {"source": "feedback de clientes", "content": "Proximidade com clientes tech gera alta percepção de valor e retenção em nicho exigente", "confidence": "Média"}, {"source": "análise de mercado", "content": "Maturidade digital alta (8/10) posiciona para adoção rápida de IA na operação jurídica", "confidence": "Média"}], "weaknesses": [{"source": "fato", "content": "Dependência crítica do sócio fundador para vendas e relacionamento comercial", "confidence": "Alta"}, {"source": "fato", "content": "Ausência de área de vendas estruturada limita crescimento a modelo orgânico", "confidence": "Alta"}, {"source": "fato", "content": "Board composto por sócios operacionais sem formação em gestão empresarial", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Falta de plano de carreira definido dificulta retenção em mercado com escassez de talentos", "confidence": "Média"}], "opportunities": [{"source": "análise de mercado", "content": "Marco Legal da IA em regulamentação criará demanda massiva por consultoria especializada", "confidence": "Alta"}, {"source": "fato", "content": "REDATA (MP 1.318/2025) abre mercado de datacenters para assessoria jurídica tributária e digital", "confidence": "Alta"}, {"source": "fato", "content": "ECA Digital (Lei 15.211/2025) gera nova vertical de compliance para empresas de tecnologia", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Consolidação do setor permite posicionamento como alvo de aquisição por bancas full-service", "confidence": "Média"}]}'::jsonb, '{"legal": ["Marco Legal da IA iminente: posicionamento antecipado como especialista gera vantagem competitiva decisiva", "Lei 15.211/2025 (ECA Digital) cria demanda imediata por consultoria em proteção de dados de menores", "Reforma Tributária (IVA para serviços) exige revisão de precificação e markup para manter margem de 40%"], "social": ["Hiperespecialização valorizada: empresas preferem boutiques técnicas a bancas generalistas para temas digitais", "Escassez de advogados seniores em tecnologia dificulta escala sem perda de qualidade técnica e cultura", "Clientes tech exigem comunicação ágil e proximidade; modelo de sócios operacionais é diferencial competitivo"], "summary": "Cenário altamente favorável para Direito Digital: regulação crescente (IA, LGPD, ECA Digital) gera demanda, mas SELIC alta e escassez de talentos exigem eficiência operacional e automação para escalar sem comprometer margens.", "economic": ["SELIC 15% a.a. encarece expansão alavancada; crescimento deve priorizar capital próprio e eficiência operacional", "Desemprego 6.4% (mínima histórica) intensifica guerra por talentos jurídicos seniores em Direito Digital", "PIB +2.2% e setor de serviços aquecido sustentam demanda B2B, mas clientes buscam eficiência jurídica vs. custo"], "political": ["MP 1.317/2025 fortalece ANPD: aumento de fiscalização e multas cria demanda urgente por consultoria LGPD especializada", "Tensão fiscal moderada pode atrasar investimentos de clientes tech, impactando contratação de serviços jurídicos premium", "MP 1.318/2025 (REDATA) abre nicho estratégico: datacenters precisarão de assessoria jurídica para regime especial"], "environmental": ["ESG ganha relevância em contratos tech; assessoria em cláusulas de sustentabilidade digital é oportunidade", "Datacenters (REDATA) enfrentam exigências de eficiência energética; nicho jurídico emergente para o escritório", "Baixo impacto ambiental direto, mas clientes tech demandam compliance ESG em due diligence e contratos"], "technological": ["IA Generativa na produção jurídica pressiona margens; automação é requisito para manter lucratividade >40%", "Softwares CLM e consultorias de TI ameaçam serviços básicos de compliance LGPD; foco deve ser alto valor agregado", "Legal Operations como padrão de mercado: controle de horas, markup e lucratividade por conta é imperativo"]}'::jsonb, '{"summary": "Setor de Direito Digital apresenta crescimento robusto impulsionado por regulação (LGPD, Marco IA, ECA Digital), mas enfrenta pressões estruturais: escassez de talentos sêniores, automação por IA ameaçando serviços básicos e entrada de consultorias tech no compliance. Para Assis e Mendes, a atratividade é média-alta condicionada à capacidade de: (1) integrar IA na operação, (2) reter talentos via plano de carreira, (3) construir marca institucional superior ao sócio fundador, e (4) estruturar vendas outbound. A hiperespecialização e proximidade com clientes tech são diferenciais defensáveis, mas exigem escala profissionalizada para capturar oportunidades como REDATA e Marco Legal da IA.", "buyer_power": "Poder médio-alto: empresas cautelosas com custos fixos buscam eficiência jurídica. SELIC 15% pressiona orçamentos corporativos. Clientes tech comparam preços e exigem transparência em honorários, forçando padronização de markup.", "supplier_power": "Poder alto: escassez crítica de advogados sêniores em Direito Digital/Tech. Profissionais qualificados têm alto poder de barganha salarial. Custo de retenção elevado impacta diretamente a margem de 40% almejada pelo escritório.", "disruption_ai_data": "Disrupção alta: IA generativa transforma produção jurídica. Escritórios adotam automação para manter margens. Quem não integrar IA perderá competitividade. Oportunidade: usar IA para escalar sem perder qualidade técnica.", "threat_substitutes": "Ameaça alta: softwares CLM substituem trabalho jurídico básico. Consultorias de TI (Big4) oferecem compliance LGPD. IA generativa automatiza produção de documentos, ameaçando serviços commoditizados do portfólio.", "competitive_rivalry": "Rivalidade alta: bancas tradicionais (Opice Blum, Baptista Luz) abrem áreas de Digital Law. Mercado fragmentado com consolidação via M&A. Automação pressiona preços do contencioso de massa, exigindo diferenciação por especialização e proximidade.", "threat_new_entrants": "Ameaça média: barreira técnica alta em Direito Digital, mas capital baixo para iniciar. Regulação crescente (LGPD, IA) atrai novos players. Normas OAB limitam publicidade, mas não impedem entrada de boutiques especializadas.", "buyer_power_intensity": "Média", "overall_attractiveness": "Média", "strategic_implications": ["Implementar IA generativa para automação de documentos e ganho de produtividade, protegendo margem de 40%", "Criar programa de retenção de talentos com plano de carreira claro para mitigar escassez de mão de obra sênior", "Estruturar parcerias estratégicas com consultorias tech e ecossistemas de startups para diversificar canais de aquisição", "Desenvolver produtos jurídicos premium de alto valor percebido (compliance IA, ECA Digital) para fugir da commoditização"], "supplier_power_intensity": "Alta", "disruption_ai_data_intensity": "Alta", "threat_substitutes_intensity": "Alta", "competitive_rivalry_intensity": "Alta", "power_partnerships_ecosystems": "Poder estratégico alto: parcerias com consultorias tech, associações setoriais e ecossistemas de startups ampliam alcance. Integração com plataformas Legal Tech e alianças com datacenters (MP 1.318/2025) criam canais de aquisição.", "threat_new_entrants_intensity": "Média", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": "Fundação de controles financeiros e IA no Mês 1, estruturação comercial outbound no Mês 2, consolidação com plano de carreira e marca institucional no Mês 3.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Estabelecer infraestrutura de controle financeiro e iniciar implementação de IA para produção jurídica", "investment": "R$ 35.000 - R$ 55.000", "key_results": ["Implementar sistema de controle de horas com 100% dos advogados registrando atividades diariamente", "Definir markup padrão por tipo de serviço (consultivo 2.5x, contencioso 3x, LGPD 2.8x) e documentar", "Selecionar e contratar plataforma de IA jurídica com POC validado em 3 casos reais"], "aligned_recommendation": "Implementação de IA na Produção Jurídica + Sistema de Controle de Horas e Markup"}, {"focus": "Crescimento", "month": "Mês 2", "objective": "Estruturar área comercial outbound e criar dashboard de lucratividade operacional", "investment": "R$ 45.000 - R$ 70.000", "key_results": ["Contratar 1 SDR e implementar CRM (HubSpot/Pipedrive) com funil de vendas configurado", "Criar dashboard de lucratividade por conta e por advogado com dados de 100% dos projetos ativos", "Desenvolver ICP documentado e playbook de vendas com scripts para prospecção de empresas tech"], "aligned_recommendation": "Estruturação de Área Comercial Outbound com Metodologia Definida"}, {"focus": "Consolidação", "month": "Mês 3", "objective": "Consolidar operação comercial, iniciar plano de carreira e fortalecer marca institucional", "investment": "R$ 40.000 - R$ 65.000", "key_results": ["Gerar mínimo de 10 reuniões qualificadas via outbound e converter 1-2 novos clientes recorrentes", "Lançar plano de carreira com 5 níveis e critérios objetivos comunicado a 100% da equipe", "Publicar 8 conteúdos técnicos no LinkedIn institucional com engajamento médio de 50+ interações"], "aligned_recommendation": "Plano de Carreira + Fortalecimento da Marca Institucional"}], "success_metrics": ["Redução de 15% no tempo médio de produção de peças jurídicas via IA", "Pipeline comercial com mínimo de 20 leads qualificados ao final dos 90 dias", "100% dos advogados com visibilidade de lucratividade individual e plano de carreira definido"], "total_investment": "R$ 120.000 - R$ 190.000"}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Implementar controles financeiros (horas/markup/lucratividade por conta), iniciar automação com IA e definir produtos padronizados", "Médio Prazo (6-12 meses): Estruturar vendas outbound, criar plano de carreira com níveis claros e lançar contratos de recorrência anual", "Longo Prazo (12+ meses): Consolidar marca institucional superior ao fundador, escalar equipe com Academia A&M e capturar demanda do Marco Legal da IA"], "key_findings": ["Cenário regulatório altamente favorável: LGPD, Marco IA e ECA Digital criam demanda estrutural para os próximos 3-5 anos", "Modelo hora-avulsa limita previsibilidade; migrar para assinaturas mensais e contratos anuais é imperativo", "Marca institucional fraca vs. marca pessoal do fundador representa risco de continuidade e teto de crescimento"], "main_findings": ["FORÇA: Alta especialização técnica em Direito Digital/LGPD com reputação de proximidade e foco em lucratividade >40%", "FRAQUEZA: Dependência comercial do sócio fundador e processos de vendas não estruturados (crescimento apenas orgânico)", "OPORTUNIDADE: Regulação crescente (Marco IA, ECA Digital, REDATA) gera demanda explosiva para serviços especializados", "AMEAÇA: Automação por IA e consultorias tech entrando no compliance pressionam serviços básicos e margens"], "important_notes": ["Escassez de talentos seniores em Direito Digital é gargalo crítico para escalar sem perder qualidade", "SELIC a 15% exige eficiência operacional rigorosa para manter margem de 40%", "Sócios operacionais no board precisam de assessment de perfil para funções estratégicas"], "central_challenge": "Transformar boutique jurídica dependente do sócio fundador em plataforma escalável com vendas estruturadas, mantendo margem >40% e qualidade técnica durante o crescimento.", "executive_summary": "Assis e Mendes está posicionada em mercado aquecido (Direito Digital/LGPD) com regulação crescente gerando demanda. Porém, a dependência do fundador, ausência de vendas outbound e falta de plano de carreira limitam escala. A estratégia exige profissionalização urgente: automação por IA, estruturação comercial e fortalecimento da marca institucional para capturar oportunidades do Marco Legal da IA e REDATA.", "strategic_priorities": ["Implementar IA na produção jurídica para liberar sócios e manter margens", "Estruturar área comercial outbound com metodologia, funções e processos definidos", "Criar plano de carreira e Academia A&M para reter talentos e construir marca institucional"], "overall_recommendation": "Profissionalizar agora: a janela de oportunidade regulatória é limitada. Priorize automação, vendas outbound e marca institucional para escalar sem depender do fundador."}'::jsonb, '{"sam": "R$ 1.8B - 3.5B", "som": "R$ 15M - 35M", "tam": "R$ 18B - 25B", "cagr": "+18-22% a.a. (baseado em: crescimento regulação IA/dados + MP 1.317/2025)", "summary": "Mercado de Direito Digital em expansão acelerada. Assis e Mendes ocupa ~0.5% do SAM com potencial de 3-5x via estruturação comercial e redução de dependência do fundador.", "assumptions": ["Mercado jurídico BR ~R$150B; Direito Digital/LGPD = 12-17% (CESA 2024)", "SAM: Empresas tech + LGPD em SP = ~15% do TAM (proxy IBGE/Sebrae)", "SOM: Market share boutique especializada 0.8-1.4% do SAM (benchmark)"], "confidence_level": 58, "calculation_notes": "TAM derivado de estudos CESA/FGV sobre mercado jurídico. SAM filtrado por nicho tech/LGPD em SP. SOM baseado em receita atual (R$3-5M) como % do SAM estimado.", "data_sources_used": {"direct_data": ["Receita declarada: R$ 3M-5M/ano", "CNAE 6911-4-01 (Serviços Jurídicos)"], "proxy_calculations": ["Concorrentes (Opice Blum, Baptista Luz) estimados em R$ 30-80M cada", "Participação de boutiques digitais: 8-12% do segmento LGPD"], "benchmark_extrapolations": ["Mercado jurídico total Brasil: R$ 140-160B (CESA 2024)", "Crescimento Direito Digital: +20-25% a.a. (Legal Tech Report)"]}, "estimation_method": "proxy_concorrentes"}'::jsonb, '{"summary": "Assis e Mendes possui diferencial técnico em Direito Digital e LGPD comparável aos líderes, mas opera com modelo artesanal de vendas e governança. Opice Blum lidera em thought leadership e geração de demanda via conteúdo. Baptista Luz se destaca em eficiência operacional com Legal Ops maduro. Patricia Peck demonstra sucesso em transformar marca pessoal em institucional. Os gaps críticos residem na estruturação comercial (crescimento ainda orgânico), profissionalização do board (sócios operacionais sem especialização em gestão) e formalização de carreira. Para escalar de R$3-5M para R$10M+ mantendo margem >40%, é imperativo adotar: (1) time de BD com metodologia outbound, (2) dashboard de rentabilidade por conta/advogado, e (3) programa de partnership com critérios objetivos.", "best_practices": ["Opice Blum: produção massiva de conteúdo técnico (livros, cursos) gerando autoridade e leads inbound", "Baptista Luz: estrutura de Legal Ops com métricas de rentabilidade por cliente e automação de processos", "Patricia Peck: marca pessoal institucionalizada que transcende o fundador, com franquias de conhecimento"], "performance_gaps": ["Ausência de área comercial estruturada vs. concorrentes com times de BD e marketing digital dedicados", "Dependência do sócio fundador para vendas, enquanto rivais têm marca institucional consolidada", "Falta de plano de carreira formalizado vs. bancas com trilhas claras de progressão e retenção de talentos"], "competitors_analyzed": ["Opice Blum Advogados", "Baptista Luz Advogados", "Patricia Peck (Pinheiro Neto)"]}'::jsonb, '{"raise": ["Automação com IA para produção jurídica e controle de métricas", "Transparência radical: dashboards em tempo real para clientes", "Programas de formação interna para criar talentos especializados"], "create": ["Assinatura jurídica mensal com escopo definido e preço fixo", "Academia A&M: certificação interna + employer branding tech", "Motor de vendas outbound com SDRs especializados em tech"], "reduce": ["Tempo de sócios em tarefas operacionais e revisões rotineiras", "Customização excessiva de contratos padrão (usar templates IA)", "Reuniões presenciais obrigatórias para alinhamentos simples"], "summary": "A estratégia transforma Assis e Mendes de boutique dependente do fundador em plataforma jurídica escalável. Elimina-se o modelo hora-avulsa e networking pessoal, criando assinaturas mensais previsíveis e vendas outbound estruturadas. A automação por IA libera sócios para estratégia enquanto dashboards em tempo real geram diferenciação radical. A Academia A&M resolve escassez de talentos e constrói marca institucional, permitindo crescimento com margem >40% e menor risco operacional.", "eliminate": ["Cobrança por hora avulsa sem previsibilidade para o cliente", "Dependência de networking pessoal do sócio fundador para vendas", "Relatórios jurídicos extensos e burocráticos sem valor percebido"], "new_value_curve": "Advocacia tech-first com precificação previsível, transparência via dashboards e marca institucional que supera dependência de sócios."}'::jsonb, '{"summary": "Estruturar vendas outbound para reduzir dependência do fundador, produtizar serviços com markup padrão e criar recorrência via contratos anuais com expansão sistemática.", "leap_loop": {"name": "LEAP Loop", "type": "acquisition", "steps": ["Land: Prospects chegam via conteúdo especializado em LGPD/IA, palestras em eventos de tech, indicações de clientes e LinkedIn dos sócios.", "Engage: Webinars gratuitos sobre compliance digital, newsletter jurídica para CTOs/DPOs, diagnósticos rápidos de risco LGPD gratuitos.", "Activate: Reunião consultiva com sócio, proposta de projeto-piloto (ex: gap analysis LGPD) com preço acessível e entrega rápida.", "Propagate: Programa de indicação com benefícios, cases de sucesso publicados, co-marketing com empresas de tech parceiras."], "metrics": ["CAC por canal (Inbound vs Outbound vs Indicação)", "Taxa de conversão Lead → Reunião → Proposta → Cliente", "Coeficiente de indicação (clientes que indicam / total clientes)", "Tempo médio do ciclo de vendas"], "bottleneck": "Dependência do sócio fundador para fechamento comercial e ausência de equipe de vendas estruturada limitam capacidade de conversão em escala."}, "scale_loop": {"name": "SCALE Loop", "type": "monetization", "steps": ["Satisfy: Entregas com SLA claro, comunicação proativa via portal do cliente, relatórios mensais de valor entregue e riscos mitigados.", "Convert: Modelo híbrido (retainer mensal + success fee em contencioso), pacotes produtizados de compliance com markup padronizado.", "Loop Back: Contratos anuais com renovação automática, check-ins trimestrais de relacionamento, alertas regulatórios personalizados.", "Expand: Upsell para novas áreas (contencioso, M&A tech), cross-sell entre empresas do mesmo grupo, treinamentos in-company."], "metrics": ["LTV por cliente e por segmento", "Taxa de renovação de contratos (churn invertido)", "Receita de expansão / Receita total (%)", "Lucratividade por conta e por advogado"], "bottleneck": "Falta de produtização dos serviços e controle de horas dificulta precificação consistente e identificação de contas rentáveis vs deficitárias."}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "SELIC mantém-se em 15%, pressionando custos de expansão. Demanda por Direito Digital cresce moderadamente com ECA Digital e dosimetria ANPD. Concorrência acirra: Opice Blum e Baptista Luz expandem, bancas tradicionais abrem áreas digitais. Escassez de talentos seniores eleva salários 15-20%. Crescimento orgânico leva faturamento a R$5,5M, mas margem comprime para 38% sem automação.", "probability": 60, "required_actions": ["Implementar IA generativa na produção jurídica para manter margem acima de 40%", "Definir markup padronizado por tipo de serviço e controlar horas rigorosamente", "Criar programa de formação interna para desenvolver talentos juniores", "Estruturar plano de carreira e OKRs trimestrais para retenção de equipe"]}, "summary": "O cenário mais provável (60%) exige foco em eficiência operacional: automação, controle de horas e padronização de markup são imperativos para manter margem de 40% com SELIC a 15%. A escassez de talentos seniores é o principal gargalo para escalar sem perder qualidade. A dependência do sócio fundador representa risco estrutural em qualquer cenário. Prioridades estratégicas: (1) implementar IA na produção jurídica, (2) estruturar área comercial outbound, (3) criar plano de carreira para reter talentos, (4) fortalecer marca institucional. O cenário otimista depende de capturar demanda do Marco Legal da IA antes dos concorrentes; o pessimista exige resiliência financeira e foco em serviços de alto valor agregado.", "optimistic": {"name": "Cenário Otimista", "description": "Marco Legal da IA aprovado em 2025 gera onda de demanda por adequação jurídica. SELIC recua para 12% até 2026, facilitando contratações. ANPD fortalecida (MP 1.317/2025) intensifica fiscalização, multiplicando projetos de compliance. Assis e Mendes captura market share de bancas tradicionais lentas em adaptar-se, atingindo R$7M de faturamento mantendo margem de 45%.", "probability": 20, "required_actions": ["Contratar 3-4 advogados seniores especializados em IA antes da aprovação do Marco Legal", "Lançar pacote de serviços ''Adequação IA + LGPD'' com precificação premium", "Estruturar área comercial outbound para capturar demanda regulatória emergente", "Investir em certificação ISO 27001 para diferenciar-se de consultorias de TI"]}, "pessimistic": {"name": "Cenário Pessimista", "description": "Reforma Tributária eleva carga sobre serviços (IVA 25%+), comprimindo margens. Recessão técnica reduz investimentos de empresas tech em compliance. Softwares CLM e consultorias de TI capturam trabalho básico de LGPD. Grande banca adquire concorrente boutique, intensificando guerra de preços. Dependência do sócio fundador expõe vulnerabilidade. Faturamento estagna em R$3,5M com margem de 30%.", "probability": 20, "required_actions": ["Reduzir custos fixos e priorizar contratos recorrentes de alto valor", "Acelerar transição de liderança: sócio fundador em papel estratégico, não operacional", "Focar em contencioso estratégico (success fee) menos sensível a preço", "Avaliar fusão ou parceria estratégica com banca complementar"]}, "mitigation_tactics": ["Diversificar receita entre consultoria LGPD, contencioso digital e adequação IA para reduzir dependência de um único serviço", "Automatizar produção jurídica repetitiva com IA generativa, protegendo margem contra pressão de preços", "Construir marca institucional ''Assis e Mendes'' via thought leadership (artigos, eventos) para reduzir dependência do sócio fundador", "Criar reserva de caixa equivalente a 6 meses de operação para atravessar cenários adversos sem demissões"], "early_warning_signals": ["Queda na taxa de conversão de propostas comerciais (sinal de guerra de preços ou perda de competitividade)", "Aumento de turnover de advogados seniores acima de 15% ao ano (escassez de talentos se agravando)", "ANPD reduzindo ritmo de fiscalizações ou multas (desaceleração da demanda por compliance)", "Grandes bancas anunciando aquisições de boutiques digitais (consolidação de mercado iminente)", "Reforma Tributária definindo alíquota de IVA para serviços acima de 20% (compressão de margem estrutural)"]}'::jsonb, '{"summary": "O BSC alinha a transição de boutique dependente do fundador para plataforma escalável: receita recorrente e margem >40% (Financeiro), crescimento via outbound e alta percepção de valor (Cliente), automação e controle por dashboards (Processos), e Academia A&M para escalar talentos sem diluir cultura (Aprendizado). A marca institucional substitui a dependência pessoal.", "customer": ["Aumentar base de clientes ativos em 60% via vendas outbound estruturadas", "Elevar NPS para >75 com percepção de valor superior à concorrência"], "financial": ["Atingir R$ 7M de receita com 50% via assinaturas recorrentes até 2026", "Manter margem líquida >40% com markup padronizado por tipo de serviço"], "learning_growth": ["Lançar Academia A&M formando 10 advogados/ano com DNA institucional", "Estruturar plano de carreira com trilhas claras e metas trimestrais"], "internal_processes": ["Automatizar 40% das tarefas repetitivas com IA até Q4/2025", "Implantar dashboards de lucratividade por conta e advogado em tempo real"]}'::jsonb, '{"score": "8.2/10", "summary": "A estratégia recomendada prioriza eficiência antes de escala, alinhada ao cenário macroeconômico de SELIC a 15% e à escassez de talentos seniores. A sequência de implementação é: (1) IA + controles operacionais nos primeiros 6 meses para criar capacidade ociosa rentável, (2) área comercial outbound entre meses 4-9 para converter capacidade em receita, (3) plano de carreira e marca institucional em paralelo para sustentar crescimento e reduzir dependência do fundador. O investimento total de R$ 380-630k em 12 meses deve gerar incremento de 25-40% no faturamento mantendo margem >40%. Próximos passos imediatos: (1) selecionar e contratar plataforma de IA jurídica até semana 4, (2) mapear processos atuais e definir markup padrão até semana 6, (3) iniciar recrutamento de SDR até semana 8. A revisão trimestral permitirá ajustes táticos, enquanto os gatilhos extraordinários garantem resposta rápida a mudanças regulatórias (Marco Legal da IA) ou competitivas.", "criteria": ["ROI e Preservação de Margem (40%) - Capacidade de manter lucratividade acima de 40% durante e após implementação, considerando SELIC a 15% e custo de capital elevado", "Risco Operacional e de Execução - Probabilidade de sucesso considerando recursos atuais, dependência do sócio fundador, escassez de talentos seniores e capacidade de manter qualidade técnica durante escala", "Velocidade de Impacto e Sustentabilidade - Tempo para geração de resultados mensuráveis e capacidade de criar vantagem competitiva sustentável frente à entrada de grandes bancas no segmento digital"], "alternatives": ["Crescimento Orgânico Acelerado com Eficiência Operacional - Foco em automação, padronização de processos e fortalecimento da marca institucional, mantendo estrutura enxuta e maximizando lucratividade através de tecnologia (IA jurídica) e processos otimizados", "Expansão Estruturada com Área Comercial Outbound - Investimento prioritário em estruturação de vendas ativas, contratação de equipe comercial dedicada e campanhas de marketing B2B, aceitando compressão temporária de margem para acelerar crescimento de receita", "Consolidação e Profissionalização do Board - Priorização da governança corporativa, redução da dependência do sócio fundador, implementação de plano de carreira robusto e preparação para eventual M&A ou entrada de sócio investidor"], "review_cycle": {"frequency": "Trimestral (reuniões de revisão estratégica nos meses 3, 6, 9 e 12)", "extraordinary_triggers": ["Aprovação do Marco Legal da IA (oportunidade de captura de mercado - acionar em até 15 dias)", "Perda de cliente que represente >10% do faturamento", "Saída de advogado sênior ou coordenador", "Margem de lucratividade abaixo de 35% por 2 meses consecutivos", "Entrada de grande banca (top 10) com oferta agressiva no nicho de Direito Digital em SP", "Mudança significativa na regulamentação da ANPD ou Reforma Tributária impactando serviços"]}, "score_comparison": "+18% acima da segunda opção (Expansão Estruturada: 6.9/10) e +31% acima da terceira (Consolidação Board: 6.3/10)", "monitoring_metrics": ["Lucratividade por conta e por advogado (meta: >40% média, mínimo 35% por conta)", "Taxa de utilização (horas faturadas / horas trabalhadas) - meta: >75%", "CAC (Custo de Aquisição de Cliente) e LTV (Lifetime Value) - meta: LTV/CAC >3x", "NPS (Net Promoter Score) de clientes - meta: >70", "Percentual de vendas originadas pela marca vs. sócio fundador (meta: 70% marca em 18 meses)", "Taxa de retenção de talentos (advogados pleno/sênior) - meta: >85% anual", "Tempo médio de entrega por tipo de serviço (baseline + redução de 20% com IA)"], "recommended_option": "Crescimento Orgânico Acelerado com Eficiência Operacional", "final_recommendation": "A melhor opção é Crescimento Orgânico Acelerado com Eficiência Operacional, pois maximiza ROI em cenário de juros altos, preserva margem de 40%, reduz riscos de escala prematura e cria fundação tecnológica para crescimento sustentável.", "priority_recommendations": [{"title": "Implementação de IA na Produção Jurídica + Sistema de Controle de Horas e Markup", "budget": "R$ 80.000 - R$ 150.000 (licenças IA: R$ 3-5k/mês + implementação sistema: R$ 40-60k + consultoria processos: R$ 30-50k)", "priority": 1, "timeline": "3-6 meses", "description": "Adotar plataforma de IA generativa jurídica (ex: Harvey, Lexis+ AI ou solução nacional) integrada ao sistema de gestão do escritório. Implementar controle rigoroso de horas trabalhadas vs. faturadas, definindo markup padrão por tipo de serviço (consultivo: 2.5x, contencioso: 3x, projetos LGPD: 2.8x). Criar dashboard de lucratividade por conta e por advogado. Meta: reduzir 25% do tempo em tarefas repetitivas e aumentar capacidade produtiva em 30% sem novas contratações imediatas."}, {"title": "Estruturação de Área Comercial Outbound com Metodologia Definida", "budget": "R$ 180.000 - R$ 280.000/ano (salários: R$ 12-18k/mês + CRM: R$ 2k/mês + marketing de suporte: R$ 3-5k/mês)", "priority": 2, "timeline": "4-9 meses", "description": "Contratar 1 SDR (Sales Development Representative) e 1 Closer com experiência em vendas B2B complexas. Implementar CRM (HubSpot ou Pipedrive) com funil de vendas estruturado. Definir ICP (Ideal Customer Profile): empresas de tecnologia com 50-500 funcionários e empresas tradicionais em transformação digital. Criar playbook de vendas com scripts, materiais e cadência de prospecção. Meta: gerar 15-20 reuniões qualificadas/mês e converter 3-4 novos clientes recorrentes/mês até mês 9."}, {"title": "Plano de Carreira + Fortalecimento da Marca Institucional", "budget": "R$ 120.000 - R$ 200.000 (consultoria RH: R$ 40-60k + marketing institucional: R$ 50-80k + certificações: R$ 30-60k)", "priority": 3, "timeline": "6-12 meses", "description": "Desenvolver plano de carreira com 5 níveis claros (Advogado Jr → Pleno → Sênior → Coordenador → Sócio), com critérios objetivos de promoção baseados em: horas faturadas, satisfação do cliente, contribuição para conhecimento interno e captação. Criar programa de mentoria cruzada para reduzir dependência do sócio fundador. Investir em posicionamento da marca Assis e Mendes através de: (1) conteúdo técnico de alta qualidade no LinkedIn, (2) participação em eventos de tecnologia como palestrantes, (3) certificações institucionais (ISO 27001). Meta: 70% das vendas originadas pela marca (não pelo sócio) em 18 meses."}]}'::jsonb, 'completed', NULL, 136230, true, false, false, 'WGWK5G8T', '2025-11-27 15:03:43.844024+00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-27 15:00:55.32687+00'::timestamptz, '2025-11-28 05:44:03.770068+00'::timestamptz, '2025-11-27 15:03:11.263815+00'::timestamptz, NULL)
